"""
Compatibility wrapper to defer binding of tiktoken dependency.

This module provides the TiktokenTokenizer class that implements the
Tokenizer protocol using tiktoken under the hood, but only imports
and instantiates it when actually needed (runtime), not at import time.

This supports the Deferred Binding Time tactic by allowing tokenizer
selection to be configured at runtime.
"""
import importlib.util
from .base import Tokenizer


class TiktokenTokenizer(Tokenizer):
    """
    Tokenizer that delegates to tiktoken for GPT-4-like tokenization.
    Only imports tiktoken at runtime when first used, avoiding hard
    compile-time dependency.
    """

    def __init__(self):
        # Initialize minimal required state; defer tiktoken import
        super().__init__()
        self._enc = None
        self._mergeable_ranks = None
        self._byte_shuffle = None
        self._inverse_byte_shuffle = None

    @property
    def enc(self):
        if self._enc is None:
            import tiktoken
            self._enc = tiktoken.get_encoding("cl100k_base")
        return self._enc

    @property
    def mergeable_ranks(self):
        if self._mergeable_ranks is None:
            self._mergeable_ranks = self.enc._mergeable_ranks
        return self._mergeable_ranks

    @property
    def byte_shuffle(self):
        if self._byte_shuffle is None:
            self._byte_shuffle = {
                i: self.mergeable_ranks[bytes([i])] for i in range(256)
            }
        return self._byte_shuffle

    @property
    def inverse_byte_shuffle(self):
        if self._inverse_byte_shuffle is None:
            self._inverse_byte_shuffle = {v: k for k, v in self.byte_shuffle.items()}
        return self._inverse_byte_shuffle

    def train(self, text, vocab_size, verbose=False):
        raise NotImplementedError("TiktokenTokenizer is pretrained and cannot be trained.")

    def encode(self, text):
        # Encode using tiktoken's internal encoding
        ids = self.enc.encode(text)
        return ids

    def decode(self, ids):
        # Decode using tiktoken's internal decoding
        return self.enc.decode(ids)


def get_gpt4_tokenizer():
    """
    Factory function to get a GPT-4-compatible tokenizer.
    Defer tiktoken import until actually needed.

    Returns:
        TiktokenTokenizer: a tokenizer instance using tiktoken
    """
    return TiktokenTokenizer()
